// generated by build-games: content/games/<slug>.html -> bu fayl. Əl ilə dəyişmə; node scripts/build-games.mjs işlət.
export default "<!doctype html>\n<html lang=\"az\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width,initial-scale=1,maximum-scale=1,user-scalable=no\">\n<title>Quş uçuşu</title>\n<style>\n*{box-sizing:border-box;-webkit-tap-highlight-color:transparent}\nhtml,body{margin:0;min-height:100%;background:radial-gradient(circle at 50% 0,#17224a,#070b18 70%);color:#e8f0ff;font-family:system-ui,\"Segoe UI\",Roboto,Arial,sans-serif;-webkit-user-select:none;user-select:none}\nbody{display:flex;justify-content:center;padding:10px}\n.wrap{width:100%;max-width:460px;text-align:center}\nh1{margin:6px 0 8px;font-size:24px;letter-spacing:.5px}\n.hud{display:flex;justify-content:space-between;gap:8px;margin:6px 0;font-size:15px}\n.hud span{flex:1;background:#ffffff12;border:1px solid #ffffff22;border-radius:10px;padding:6px 8px}\ncanvas{display:block;margin:0 auto;width:100%;height:auto;border-radius:14px;border:2px solid #4cc9f0;background:#0a1128;touch-action:none;box-shadow:0 0 24px #4cc9f044}\nbutton{font:inherit;color:#fff;background:linear-gradient(#3a86ff,#2563eb);border:0;border-radius:12px;padding:10px 16px;cursor:pointer;box-shadow:0 3px 0 #1b3f9a}\nbutton:active{transform:translateY(2px);box-shadow:none}\n.row{display:flex;gap:8px;justify-content:center;margin:10px 0;flex-wrap:wrap}\n.hint{opacity:.7;font-size:13px;margin:6px 0}\n.msg{min-height:24px;font-weight:700;color:#ffd166;margin:6px 0}\ncanvas{max-width:360px;cursor:pointer}\n</style>\n</head>\n<body>\n<div class=\"wrap\">\n<h1>🐤 Quş uçuşu</h1>\n<div class=\"hud\"><span>Xal: <b id=\"sc\">0</b></span><span>Rekord: <b id=\"bs\">0</b></span></div>\n<canvas id=\"c\" width=\"320\" height=\"480\"></canvas>\n<p class=\"hint\">Toxun, kliklə və ya Boşluq düyməsini bas — quş yuxarı uçur</p>\n</div>\n<script>\nconst W = 320, H = 480, GRAV = 0.42, FLAP = -7, GAP = 135, PW = 54, GROUND = 56, SPEED = 2.4;\nconst cv = document.getElementById('c'), ctx = cv.getContext('2d');\nconst $ = id => document.getElementById(id);\nlet bird, pipes, score, best = 0, state, frame, deadT, acc = 0, last = 0;\ntry { best = +localStorage.getItem('nibras_qus') || 0; } catch (e) {}\n$('bs').textContent = best;\n\nfunction reset() {\n  bird = { x: 90, y: H / 2, v: 0, r: 13 }; pipes = []; score = 0; frame = 0; deadT = 0; state = 'ready';\n  $('sc').textContent = 0;\n}\nfunction flap() {\n  if (state === 'dead') { if (deadT > 25) reset(); return; }\n  if (state === 'ready') state = 'play';\n  bird.v = FLAP;\n}\nfunction die() {\n  state = 'dead'; deadT = 0;\n  if (score > best) { best = score; $('bs').textContent = best; try { localStorage.setItem('nibras_qus', best); } catch (e) {} }\n}\nfunction update() {\n  frame++;\n  if (state === 'ready') { bird.y = H / 2 + Math.sin(frame / 10) * 7; return; }\n  if (state === 'dead') { deadT++; if (bird.y < H - GROUND - bird.r) { bird.v += GRAV; bird.y += bird.v; } return; }\n  bird.v += GRAV; bird.y += bird.v;\n  if (frame % 92 === 1) pipes.push({ x: W, top: 60 + Math.random() * (H - GROUND - GAP - 120), passed: false });\n  for (const p of pipes) {\n    p.x -= SPEED;\n    if (!p.passed && p.x + PW < bird.x) { p.passed = true; score++; $('sc').textContent = score; }\n    if (bird.x + bird.r > p.x && bird.x - bird.r < p.x + PW && (bird.y - bird.r < p.top || bird.y + bird.r > p.top + GAP)) die();\n  }\n  pipes = pipes.filter(p => p.x > -PW);\n  if (bird.y + bird.r >= H - GROUND) { bird.y = H - GROUND - bird.r; die(); }\n  if (bird.y - bird.r < 0) { bird.y = bird.r; bird.v = 0; }\n}\nfunction pipe(x, y, h, flip) {\n  ctx.fillStyle = '#5bbd3c'; ctx.fillRect(x, y, PW, h);\n  ctx.fillStyle = '#7ce05a'; ctx.fillRect(x + 4, y, 8, h);\n  ctx.fillStyle = '#3f8f28'; const cy = flip ? y + h - 20 : y;\n  ctx.fillRect(x - 4, cy, PW + 8, 20);\n  ctx.strokeStyle = '#2b6a1a'; ctx.strokeRect(x - 4, cy, PW + 8, 20);\n}\nfunction draw() {\n  const g = ctx.createLinearGradient(0, 0, 0, H); g.addColorStop(0, '#4cc9f0'); g.addColorStop(1, '#bde7ff');\n  ctx.fillStyle = g; ctx.fillRect(0, 0, W, H);\n  ctx.fillStyle = '#ffffffaa';\n  for (let i = 0; i < 4; i++) { const cx = ((i * 140 - frame * 0.4) % 520 + 520) % 520 - 60; ctx.beginPath(); ctx.arc(cx, 80 + i * 50, 22, 0, 7); ctx.arc(cx + 22, 86 + i * 50, 18, 0, 7); ctx.arc(cx - 20, 88 + i * 50, 16, 0, 7); ctx.fill(); }\n  for (const p of pipes) { pipe(p.x, 0, p.top, true); pipe(p.x, p.top + GAP, H - GROUND - p.top - GAP, false); }\n  ctx.fillStyle = '#ded895'; ctx.fillRect(0, H - GROUND, W, GROUND);\n  ctx.fillStyle = '#9ccc3b'; ctx.fillRect(0, H - GROUND, W, 10);\n  ctx.fillStyle = '#c9c277'; for (let x = -(frame * SPEED) % 24; x < W; x += 24) ctx.fillRect(x, H - GROUND + 22, 12, 6);\n  ctx.save(); ctx.translate(bird.x, bird.y); ctx.rotate(Math.max(-0.5, Math.min(1.2, bird.v / 10)));\n  ctx.fillStyle = '#ffd23f'; ctx.beginPath(); ctx.arc(0, 0, bird.r, 0, 7); ctx.fill();\n  ctx.fillStyle = '#f4a100'; ctx.beginPath(); ctx.ellipse(-4, 3, 7, 4.5, Math.sin(frame / 3) * 0.5, 0, 7); ctx.fill();\n  ctx.fillStyle = '#ff6b35'; ctx.beginPath(); ctx.moveTo(9, -1); ctx.lineTo(19, 3); ctx.lineTo(9, 7); ctx.fill();\n  ctx.fillStyle = '#fff'; ctx.beginPath(); ctx.arc(5, -5, 4.5, 0, 7); ctx.fill();\n  ctx.fillStyle = '#111'; ctx.beginPath(); ctx.arc(6.5, -5, 2, 0, 7); ctx.fill();\n  ctx.restore();\n  ctx.textAlign = 'center'; ctx.fillStyle = '#fff'; ctx.strokeStyle = '#0008'; ctx.lineWidth = 4;\n  ctx.font = 'bold 44px system-ui'; ctx.strokeText(score, W / 2, 70); ctx.fillText(score, W / 2, 70);\n  ctx.font = 'bold 20px system-ui';\n  if (state === 'ready') { ctx.strokeText('Başlamaq üçün toxun', W / 2, 300); ctx.fillText('Başlamaq üçün toxun', W / 2, 300); }\n  if (state === 'dead') {\n    ctx.fillStyle = '#000a'; ctx.fillRect(40, 170, 240, 120); ctx.fillStyle = '#fff';\n    ctx.font = 'bold 28px system-ui'; ctx.fillText('Oyun bitdi', W / 2, 212);\n    ctx.font = '18px system-ui'; ctx.fillText('Xal: ' + score + '  ·  Rekord: ' + best, W / 2, 242);\n    ctx.fillText('Yenidən başlamaq üçün toxun', W / 2, 270);\n  }\n}\nfunction frameLoop(t) {\n  acc += Math.min(100, t - last); last = t;\n  while (acc >= 1000 / 60) { update(); acc -= 1000 / 60; }\n  draw(); requestAnimationFrame(frameLoop);\n}\ncv.addEventListener('pointerdown', e => { e.preventDefault(); flap(); });\naddEventListener('keydown', e => { if (e.key === ' ' || e.key === 'ArrowUp' || e.key === 'w') { e.preventDefault(); if (!e.repeat) flap(); } });\nreset(); requestAnimationFrame(t => { last = t; frameLoop(t); });\n\n</script>\n</body>\n</html>\n";
